"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

KEYS = ("max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days")
_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_INT = re.compile(r"[0-9]+\Z")
_SECTION = re.compile(r"\[(.*)\]\Z")


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None  # bytes
    max_age: int | None = None  # seconds
    naming: str = "numbered"
    offset: int = 0  # seconds
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if key == "max_size":
        if v == "off":
            return None
        m = _SIZE.match(v)
        if not m:
            raise _bad(f"bad size {v!r}")
        return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    if key == "max_age":
        if v == "off":
            return None
        m = _DUR.match(v)
        if not m:
            raise _bad(f"bad duration {v!r}")
        return int(m.group(1)) * {"m": 60, "h": 3600, "d": 86400}[m.group(2)]
    if key == "naming":
        if v not in ("numbered", "dated"):
            raise _bad(f"bad naming {v!r}")
        return v
    if key == "offset":
        m = _OFFSET.match(v)
        if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
            raise _bad(f"bad offset {v!r}")
        s = int(m.group(2)) * 3600 + int(m.group(3)) * 60
        return -s if m.group(1) == "-" else s
    if key == "keep_days" and v == "off":
        return None
    if not _INT.match(v):
        raise _bad(f"bad number {v!r}")
    n = int(v)
    if key in ("keep", "keep_days") and n < 1:
        raise _bad(f"{key} must be at least 1")
    return n


def load(path: Path):
    """Returns (defaults raw dict, {stream: raw dict}) validated."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults = None
    per = {}
    cur = None
    for line in text.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        m = _SECTION.match(line)
        if m:
            title = m.group(1)
            if title == "defaults":
                if defaults is not None:
                    raise _bad("section defaults twice")
                defaults = cur = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in per:
                    raise _bad(f"section {name} twice")
                per[name] = cur = {}
            else:
                raise _bad(f"unknown section {title!r}")
            continue
        if cur is None or "=" not in line:
            raise _bad(f"bad line {line!r}")
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip()
        if k not in KEYS:
            raise _bad(f"unknown key {k!r}")
        if k in cur:
            raise _bad(f"key {k} twice")
        cur[k] = _value(k, v)
    return defaults or {}, per


class Policy:
    def __init__(self, path: Path):
        self.defaults, self.per = load(path)

    def streams(self):
        return set(self.per)

    def settings(self, name) -> Settings:
        vals = {}
        for k in KEYS:
            if k in self.per.get(name, {}):
                vals[k] = self.per[name][k]
            elif k in self.defaults:
                vals[k] = self.defaults[k]
        return Settings(**vals)
