"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, state as state_mod, streams
from logkeep.errors import DataError, Refused
from logkeep.policy import Policy

_TIME = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.,][0-9]+)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)\Z"
)
_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_NUM = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


def parse_time(v):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(v, str):
        return None
    try:
        if _TIME.match(v):
            t = datetime.fromisoformat(v.replace(",", "."))
        elif _LEGACY.match(v):
            t = datetime.fromisoformat(v).replace(tzinfo=timezone.utc)
        else:
            return None
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def _state_err(msg):
    return DataError("state", f"state.json: {msg}")


def _check_entry(name, entry):
    if "opened" in entry and parse_time(entry["opened"]) is None:
        raise _state_err(f"{name}: bad opened")
    if "archives" in entry:
        a = entry["archives"]
        if not isinstance(a, dict):
            raise _state_err(f"{name}: archives is not an object")
        for k, v in a.items():
            if parse_time(v) is None:
                raise _state_err(f"{name}: bad time for {k}")
    if "rotations" in entry:
        r = entry["rotations"]
        if not isinstance(r, int) or isinstance(r, bool) or r < 0:
            raise _state_err(f"{name}: bad rotations")


class Archive:
    def __init__(self, name, key, gz, time=None, new=False):
        self.old = None if new else name
        self.name = name
        self.key = key
        self.gz = gz
        self.time = time
        self.new = new


def find_archives(logs, name, naming):
    prefix = f"{name}.log."
    out, seen = [], set()
    if not logs.is_dir():
        return out
    for p in logs.iterdir():
        if not p.name.startswith(prefix) or not p.is_file():
            continue
        rest = p.name[len(prefix):]
        if naming == "numbered":
            m = _NUM.match(rest)
            if not m:
                continue
            key, gz = int(m.group(1)), bool(m.group(2))
        else:
            m = _DATED.match(rest)
            if not m:
                continue
            try:
                d = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            key, gz = (d, int(m.group(2) or 1)), bool(m.group(3))
        if key in seen:
            raise DataError("archives", f"{name}: two archives in place {key}")
        seen.add(key)
        out.append(Archive(p.name, key, gz))
    return out


def _first_line_time(path):
    with path.open("rb") as f:
        line = f.readline()
    if line.endswith(b"\n"):
        line = line[:-1]
    if b" " not in line:
        return None
    try:
        return parse_time(line.split(b" ", 1)[0].decode("ascii"))
    except UnicodeDecodeError:
        return None


def run(ctx, requested, dry_run, force):
    now = ctx.now
    policy = Policy(ctx.policy_path)
    doc = ctx.state
    data = ctx.data
    logs = streams.logs_dir(data)
    existing = set(streams.active(data)) | policy.streams()
    entries = doc["streams"]
    for name, entry in entries.items():
        if name in existing:
            _check_entry(name, entry)
    for name in requested:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    names = sorted(set(requested)) if requested else sorted(existing)

    plans = []
    for name in names:
        s = policy.settings(name)
        arch = find_archives(logs, name, s.naming)
        plans.append((name, s, arch))

    out = []
    n_rot = n_rem = n_comp = 0
    actions = []  # file operations
    new_entries = {}
    for name, s, arch in plans:
        entry = entries.get(name, {})
        times = entry.get("archives", {})
        for a in arch:
            if a.name in times:
                a.time = parse_time(times[a.name])
                a.raw_time = times[a.name]
        log = streams.log_path(data, name)
        what = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what = "rotate (forced)"
            elif s.max_size is not None and size >= s.max_size:
                what = "rotate (size)"
            elif s.max_age is not None:
                opened = parse_time(entry["opened"]) if "opened" in entry else _first_line_time(log)
                if opened is not None and (now - opened) >= timedelta(seconds=s.max_age):
                    what = "rotate (age)"
            if what is None:
                what = "not due"
        rotated = what.startswith("rotate")
        arch.sort(key=lambda a: a.key, reverse=(s.naming == "dated"))
        newarc = None
        if rotated:
            if s.naming == "numbered":
                newarc = Archive(None, 0, False, now, new=True)
                arch.insert(0, newarc)
            else:
                day = now.astimezone(timezone(timedelta(seconds=s.offset))).date()
                used = {a.key[1] for a in arch if a.key[0] == day}
                if not used:
                    k = 1
                else:
                    k = 2
                    while k in used:
                        k += 1
                newarc = Archive(None, (day, k), False, now, new=True)
                arch.append(newarc)
                arch.sort(key=lambda a: a.key, reverse=True)
            newarc.raw_time = None
        # retention (positions over all archives)
        keep, removed = [], []
        limit = timedelta(days=s.keep_days) if s.keep_days is not None else None
        for pos, a in enumerate(arch, 1):
            if pos > s.keep or (limit is not None and a.time is not None and now - a.time >= limit):
                removed.append(a)
            else:
                keep.append(a)
        lines = [f"{name}: {what}"]
        tmap = {}
        for i, a in enumerate(keep, 1):
            compress = (not a.gz) and i > s.compress_after
            gz = a.gz or compress
            if s.naming == "numbered":
                base = str(i)
            else:
                base = a.key[0].isoformat() + ("" if a.key[1] == 1 else f".{a.key[1]}")
            final = f"{name}.log.{base}" + (".gz" if gz else "")
            if compress:
                n_comp += 1
            if a.new:
                lines.append(f"  new {final}")
            elif final != a.old:
                lines.append(f"  {final} <- {a.old}")
            else:
                lines.append(f"  {final}")
            if a.new:
                actions.append(("new", log, final, compress))
            elif final != a.old or compress:
                actions.append(("move", a.old, final, compress))
            if a.new:
                tmap[final] = dates.stamp(now)
            elif a.time is not None:
                tmap[final] = a.raw_time
        for a in removed:
            lines.append(f"  remove {a.old}") if not a.new else None
            if not a.new:
                actions.append(("remove", a.old))
        n_rem += sum(1 for a in removed if not a.new)
        if rotated:
            n_rot += 1
        # a new archive removed by retention: still rotated; log is emptied
        for a in removed:
            if a.new:
                actions.append(("discard", log))
        ne = {}
        if rotated:
            ne["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = tmap
        new_entries[name] = ne
        out.extend(lines)
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    # apply: read everything first, then delete, then write
    writes = []
    deletes = []
    for act in actions:
        if act[0] == "remove":
            deletes.append(logs / act[1])
        elif act[0] == "move":
            _, old, final, compress = act
            raw = (logs / old).read_bytes()
            if compress:
                raw = gzip.compress(raw, mtime=0)
            deletes.append(logs / old)
            writes.append((logs / final, raw))
        elif act[0] == "new":
            _, log, final, compress = act
            raw = log.read_bytes()
            if compress:
                raw = gzip.compress(raw, mtime=0)
            writes.append((logs / final, raw))
            writes.append((log, b""))
        elif act[0] == "discard":
            writes.append((act[1], b""))
    for p in deletes:
        p.unlink()
    for p, raw in writes:
        p.write_bytes(raw)
    doc["streams"].update(new_entries)
    state_mod.save(ctx.state_path, doc)
    return out
